import { defineConfig, minimal2023Preset } from "@vite-pwa/assets-generator/config";

// Rasterizes the real Ashkan Medical brand mark into the PNG set
// vite-plugin-pwa's manifest needs (192/512 + maskable) plus favicon.ico.
//
// The source is `src/assets/favicon-source.png` (outside public/, so it is
// never served), generated by
// `scripts/make-favicon.mjs` from the same logo the app renders in
// BrandLogo -- cropped to just the loop mark, because the full lockup
// includes a wordmark and a line of Persian text that are an illegible
// smudge at 16px. It sits on a rounded white plate for the same reason
// BrandLogo does: the mark is drawn for a light ground and loses its blue
// half against a dark browser tab.
export default defineConfig({
  headLinkOptions: { preset: "2023" },
  preset: minimal2023Preset,
  images: ["src/assets/favicon-source.png"],
});
